module dog_feeding_2dogs (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] t0_0, t0_1, t0_2, t0_3,\n    input [7:0] t1_0, t1_1, t1_2, t1_3,\n    output reg [7:0] min_T,\n    output reg done\n);\n\n    // State encoding\n    localparam [2:0] IDLE   = 3'd0;\n    localparam [2:0] INIT   = 3'd1;\n    localparam [2:0] LOOP0  = 3'd2;\n    localparam [2:0] LOOP1  = 3'd3;\n    localparam [2:0] UPDATE = 3'd4;\n    localparam [2:0] NEXT   = 3'd5;\n    localparam [2:0] DONE_ST = 3'd6;\n    \n    reg [2:0] state, next_state;\n    reg [1:0] bowl0_idx, bowl1_idx;\n    reg [7:0] min_T_reg;\n    reg [7:0] t0_val, t1_val;\n    \n    // Combinational temperature selection\n    wire [7:0] curr_t0 = (bowl0_idx == 2'd0) ? t0_0 :\n                         (bowl0_idx == 2'd1) ? t0_1 :\n                         (bowl0_idx == 2'd2) ? t0_2 : t0_3;\n    \n    wire [7:0] curr_t1 = (bowl1_idx == 2'd0) ? t1_0 :\n                         (bowl1_idx == 2'd1) ? t1_1 :\n                         (bowl1_idx == 2'd2) ? t1_2 : t1_3;\n    \n    // Absolute difference calculation\n    wire [7:0] diff = (t0_val > t1_val) ? (t0_val - t1_val) : (t1_val - t0_val);\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            min_T <= 8'd0;\n            done <= 1'b0;\n            bowl0_idx <= 2'd0;\n            bowl1_idx <= 2'd0;\n            min_T_reg <= 8'd255;\n            t0_val <= 8'd0;\n            t1_val <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    min_T_reg <= 8'd255;\n                    if (start) state <= INIT;\n                end\n                \n                INIT: begin\n                    bowl0_idx <= 2'd0;\n                    bowl1_idx <= 2'd0;\n                    t0_val <= 8'd0;\n                    t1_val <= 8'd0;\n                    state <= LOOP0;\n                end\n                \n                LOOP0: begin\n                    if (bowl0_idx == 2'd3) begin\n                        state <= DONE_ST;\n                    end else begin\n                        bowl1_idx <= 2'd0;\n                        state <= LOOP1;\n                    end\n                end\n                \n                LOOP1: begin\n                    if (bowl1_idx == 2'd3) begin\n                        bowl0_idx <= bowl0_idx + 2'd1;\n                        state <= LOOP0;\n                    end else if (bowl0_idx != bowl1_idx) begin\n                        t0_val <= curr_t0;\n                        t1_val <= curr_t1;\n                        state <= UPDATE;\n                    end else begin\n                        bowl1_idx <= bowl1_idx + 2'd1;\n                        state <= LOOP1;\n                    end\n                end\n                \n                UPDATE: begin\n                    if (diff < min_T_reg) begin\n                        min_T_reg <= diff;\n                    end\n                    bowl1_idx <= bowl1_idx + 2'd1;\n                    state <= LOOP1;\n                end\n                \n                DONE_ST: begin\n                    min_T <= min_T_reg;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule